window.bookSummaryJSON = "<p>Danielle Garrett presents Books 1-5 of the Sugar Shack Witch Mysteries, a paranormal cozy mystery series filled with magic, mystery, family squabbles, sassy heroines, and a mysterious monster hunter—all with a little sugar sprinkled on top. This bundle includes <i>Sprinkles and Sea Serpents</i>, <i>Grimoires and Gingerbread</i>, <i>Mermaids and Meringue</i>, <i>Sugar Cookies and Sirens</i>, and <i>Hexes and Honey Buns</i>.</p>"; 
